package com.muxigame.city;
import java.util.*;
import net.minecraft.core.BlockPos;
import net.minecraft.nbt.*;
import net.minecraft.network.chat.Component;
import net.minecraft.server.level.*;
import net.minecraft.world.*;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.item.*;
import net.neoforged.neoforge.event.entity.player.PlayerInteractEvent;
import net.neoforged.neoforge.network.PacketDistributor;

public final class RuralTools {
 static boolean available(net.minecraft.server.MinecraftServer s,RuralSettlement.Site site){var c=CityData.get(s).cities.get(site.city);if(c==null)return site.present;var pos=BlockPos.of(site.pos);var level=CityEconomy.level(s,c);boolean known=c.works.pending.containsKey(site.pos)||c.works.finalized&&CityWorks.at(c,site.pos)!=null;if(!known&&!level.hasChunkAt(pos))return site.present;var block=CityWorks.dataAt(s,c,site.pos);if(site.expectedBlock!=null&&!site.expectedBlock.isEmpty())return net.minecraft.core.registries.BuiltInRegistries.BLOCK.getKey(block.getBlock()).toString().equals(site.expectedBlock);if(site.kind.equals("artisan"))return CityBlockRules.workstation(block);return block.getBlock() instanceof RuralBlocks.WorkBlock work&&work.kind.equals(site.kind);}
 static void resignBlocked(net.minecraft.server.MinecraftServer s,CityData.City c,long now){var d=RuralSettlement.get(s);for(var site:d.state.sites.values()){if(!c.id.equals(site.city)||site.worker==null)continue;var p=d.state.people.get(site.worker);if(p==null||p.dead)continue;long progress=c.works.repaired+c.works.constructed;if(available(s,site)||p.role==RuralRules.Role.ARTISAN&&progress>site.progressMark){site.blockedSince=0;site.progressMark=progress;continue;}if(site.blockedSince==0)site.blockedSince=now+1;if(now+1-site.blockedSince<72000)continue;p.role=RuralRules.Role.NONE;p.workStatus="工作点连续三日失效，已离职成为居民";for(var h:c.housing.houses.values())h.workers.remove(p.id);var worker=CityMaintenance.get(s).state.workers.get(p.id);if(worker!=null)worker.enabled=false;site.worker=null;site.vacantSince=now+1;site.blockedSince=0;d.log(p.name+"离开持续失效岗位，保留居民身份和资产");d.setDirty();}}
 static final Map<UUID,UUID> selected=new HashMap<>();static final Map<UUID,BlockPos> selectedSite=new HashMap<>();
 static CityData.City city(ServerLevel l,BlockPos pos){return CityData.get(l.getServer()).cities().stream().filter(c->c.dimension.equals(l.dimension().location().toString())&&c.includes(pos)).findFirst().orElse(null);}
 static void say(ServerPlayer p,String s){p.sendSystemMessage(Component.literal("[农村] "+s));}
 static void editor(ServerPlayer p){CityEconomy.require(p.hasPermissions(2)||p.isCreative(),"需要管理员或创造权限");}
 static void register(ServerLevel l,BlockPos pos,RuralBlocks.Link link){var c=city(l,pos);if(c==null)return;var d=RuralSettlement.get(l.getServer());var state=l.getBlockState(pos);if(!(state.getBlock() instanceof RuralBlocks.WorkBlock b))return;String k=RuralSettlement.key(c.id,pos.asLong());
  if(b.kind.equals("storage")){var box=d.state.boxes.computeIfAbsent(k,a->new RuralSettlement.Box());box.city=c.id;box.pos=pos.asLong();box.present=true;
   if(link.offset!=null){long target=pos.offset(link.offset).asLong();var site=d.state.sites.get(RuralSettlement.key(c.id,target));if(site!=null){box.site=target;box.linked=true;if(box.stock.family==null)box.stock.family=site.worker==null||!d.state.people.containsKey(site.worker)?null:d.state.people.get(site.worker).family;}}
   else {var sites=d.state.sites.values().stream().filter(s->s.present&&s.city.equals(c.id)&&BlockPos.of(s.pos).distSqr(pos)<=256).sorted(Comparator.comparingDouble(s->BlockPos.of(s.pos).distSqr(pos))).toList();if(!sites.isEmpty()&&(sites.size()==1||BlockPos.of(sites.get(0).pos).distSqr(pos)<BlockPos.of(sites.get(1).pos).distSqr(pos))){link.offset=BlockPos.of(sites.getFirst().pos).subtract(pos);link.setChanged();box.site=sites.getFirst().pos;box.linked=true;var person=d.state.people.get(sites.getFirst().worker);if(box.stock.family==null)box.stock.family=person==null?null:person.family;}}
  }else{var site=d.state.sites.computeIfAbsent(k,a->new RuralSettlement.Site());site.city=c.id;site.pos=pos.asLong();if(site.worker==null||((site.expectedBlock==null||site.expectedBlock.isEmpty())&&(site.kind.isEmpty()||site.kind.equals(b.kind))))site.expectedBlock=net.minecraft.core.registries.BuiltInRegistries.BLOCK.getKey(b).toString();if(site.worker==null)site.kind=b.kind;site.present=site.expectedBlock.equals(net.minecraft.core.registries.BuiltInRegistries.BLOCK.getKey(b).toString());}d.setDirty();
 }
 static void remove(ServerLevel l,BlockPos pos){var c=city(l,pos);if(c==null)return;var d=RuralSettlement.get(l.getServer());String key=RuralSettlement.key(c.id,pos.asLong());var box=d.state.boxes.remove(key);if(box!=null)NpcStorage.drop(l,pos,l.getBlockEntity(pos) instanceof RuralBlocks.Link link?link:null,box);var site=d.state.sites.get(key);if(site!=null)site.present=false;d.setDirty();}
 public static void interact(PlayerInteractEvent.EntityInteract event){if(!(event.getEntity() instanceof ServerPlayer p)||event.getHand()!=InteractionHand.MAIN_HAND||!(p.getMainHandItem().getItem() instanceof RuralBlocks.Wand wand))return;event.setCanceled(true);event.setCancellationResult(InteractionResult.SUCCESS);
  try{editor(p);CityEconomy.require(event.getTarget() instanceof LivingEntity&&net.minecraft.core.registries.BuiltInRegistries.ENTITY_TYPE.getKey(event.getTarget().getType()).getNamespace().equals("customnpcs"),"请选择CustomNPC居民");var c=city(p.serverLevel(),event.getTarget().blockPosition());CityEconomy.require(c!=null&&c.residents.contains(event.getTarget().getUUID()),"先将NPC登记到本地城市");var d=RuralSettlement.get(p.server);var person=d.enroll(p.server,c,event.getTarget().getUUID(),event.getTarget().getName().getString());UUID previous=selected.get(p.getUUID());selected.put(p.getUUID(),person.id);if(wand.marriage&&previous!=null&&!previous.equals(person.id)){pendingPartner.put(p.getUUID(),previous);}snapshot(p,person.id,"");}catch(Exception ex){say(p,ex.getMessage());}}
 static final Map<UUID,UUID> pendingPartner=new HashMap<>();
 static void wandBlock(ServerPlayer p,BlockPos pos,boolean marriage){try{editor(p);CityEconomy.require(!marriage,"婚姻魔杖：依次右键两位NPC，再选择关系");var c=city(p.serverLevel(),pos);CityEconomy.require(c!=null&&p.serverLevel().getBlockEntity(pos) instanceof RuralBlocks.Link,"仅能绑定本城工作点或专用NPC储藏箱");var link=(RuralBlocks.Link)p.serverLevel().getBlockEntity(pos);register(p.serverLevel(),pos,link);var d=RuralSettlement.get(p.server);String key=RuralSettlement.key(c.id,pos.asLong());var site=d.state.sites.get(key);
  if(site!=null){UUID id=selected.get(p.getUUID());CityEconomy.require(id!=null&&d.state.people.containsKey(id),"先用储存魔杖选择NPC");var person=d.state.people.get(id);CityEconomy.require(person.age.ordinal()>=2&&!person.dead,"儿童、婴儿或死亡居民不能工作");CityEconomy.require(d.state.families.get(person.family).city.equals(c.id),"不能跨城绑定");CityEconomy.require(site.worker==null||site.worker.equals(id),"工作点已有人使用");for(var old:d.state.sites.values())if(Objects.equals(old.worker,id))old.worker=null;site.worker=id;var role=switch(site.kind){case "farmer"->RuralRules.Role.FARMER;case "cook"->RuralRules.Role.COOK;case "hunter"->RuralRules.Role.HUNTER;case "procurement"->RuralRules.Role.PROCUREMENT;case "baker"->RuralRules.Role.BAKER;case "supplier"->RuralRules.Role.SUPPLIER;default->RuralRules.Role.MERCHANT;};if(person.role!=role){person.trainedHours=0;person.trainingTicks=0;person.workingTicks=0;person.cropTicks=0;person.productionCredit=0;person.cookingCredit=0;person.huntingTicks=0;person.huntingSpot=null;}person.role=role;CityTradeLab.attach(p.server,c,site,person);WorkHours.config(p.server,id);selectedSite.put(p.getUUID(),pos);for(var box:d.state.boxes.values())if(box.city.equals(c.id)&&box.linked&&box.site==site.pos&&box.stock.family==null)box.stock.family=person.family;say(p,"已绑定工作点；再点击专用储藏箱关联。旧工作点已解除，转职熟练度重新累计。");}
  else{BlockPos target=selectedSite.get(p.getUUID());CityEconomy.require(target!=null&&target.distSqr(pos)<=1024,"先选择32格内工作点");var work=d.state.sites.get(RuralSettlement.key(c.id,target.asLong()));CityEconomy.require(work!=null&&work.worker!=null,"工作点没有居民");var box=d.state.boxes.get(key);CityEconomy.require(box.stock.free()==10||Objects.equals(box.stock.family,d.state.people.get(work.worker).family),"非空箱子不能转交其他家庭");link.offset=target.subtract(pos);link.setChanged();register(p.serverLevel(),pos,link);say(p,"储藏箱已关联，容量10份；关联保存在建筑数据中。");}d.state.revision++;d.setDirty();
 }catch(Exception ex){say(p,ex.getMessage());}}
 static void block(ServerPlayer p,BlockPos pos){try{var c=city(p.serverLevel(),pos);CityEconomy.require(c!=null,"请先登记村落范围");var link=(RuralBlocks.Link)p.serverLevel().getBlockEntity(pos);register(p.serverLevel(),pos,link);var d=RuralSettlement.get(p.server);var box=d.state.boxes.get(RuralSettlement.key(c.id,pos.asLong()));if(box!=null){var held=p.getMainHandItem();int meatTransferred=RuralMeat.transferItem(box.stock,held);boolean bread=held.is(Items.BREAD);if(meatTransferred>=0){}else if(bread||held.is(Items.WHEAT)){int n=RuralRules.put(List.of(box.stock),bread,Math.min(held.getCount(),box.stock.free()));held.shrink(n);}else if(p.isShiftKeyDown()&&held.isEmpty()){boolean takeBread=box.stock.bread>0;int n=RuralRules.take(List.of(box.stock),takeBread,1);if(n>0)p.getInventory().placeItemBackInInventory(new ItemStack(takeBread?Items.BREAD:Items.WHEAT,n));else{var meat=RuralMeat.withdraw(box.stock);if(!meat.isEmpty())p.getInventory().placeItemBackInInventory(meat);}}d.setDirty();say(p,"储藏：小麦"+box.stock.wheat+" 面包"+box.stock.bread+" 肉食"+RuralMeat.total(List.of(box.stock))+" / 10。持食物存入，潜行空手取1份。");return;}var site=d.state.sites.get(RuralSettlement.key(c.id,pos.asLong()));if(site.worker!=null){selected.put(p.getUUID(),site.worker);snapshot(p,site.worker,"");}else say(p,"用NPC储存魔杖先选居民，再点击工作点。");}catch(Exception ex){say(p,ex.getMessage());}}
 static void openSelected(ServerPlayer p,boolean marriage){UUID id=selected.get(p.getUUID());if(id==null)say(p,"先右键NPC选择。婚姻魔杖依次选择两人；储存魔杖再点击工作点与箱子。");else snapshot(p,id,"");}
 static void snapshot(ServerPlayer p,UUID id,String message){var d=RuralSettlement.get(p.server);var person=d.state.people.get(id);if(person==null)return;var f=d.state.families.get(person.family);var t=new CompoundTag();t.putBoolean("Rural",true);t.putString("Npc",id.toString());t.putString("Title",person.name);t.putLong("Revision",d.state.revision);t.putString("Person",CityEconomy.JSON.toJson(person));t.putString("Occupation",HouseholdCooking.name(p.server,person));t.putString("Family","家庭"+RuralRules.members(f,d.state.people).size()+"/10，餐食"+RuralRules.demand(f,d.state.people)+"份/次；小麦"+RuralRules.count(d.stocks(f.id),false)+"，面包"+RuralRules.count(d.stocks(f.id),true)+" 肉食"+RuralMeat.total(d.stocks(f.id)));t.putString("Message",message);t.putBoolean("Enabled",d.state.enabled.contains(f.city));t.putLong("Silver",CityEconomy.get(p.server).state.accounts.getOrDefault(CityEconomy.person(id),0L));t.putString("Ledger",String.join("\n",d.state.ledger.subList(Math.max(0,d.state.ledger.size()-5),d.state.ledger.size())));PacketDistributor.sendToPlayer(p,new CityNetwork.Snapshot(t));}
 static void request(ServerPlayer p,CityNetwork.Request r){try{editor(p);var d=RuralSettlement.get(p.server);UUID id=UUID.fromString(r.city());CityEconomy.require(id.equals(selected.get(p.getUUID()))&&d.state.people.containsKey(id),"请重新选择NPC");var person=d.state.people.get(id);var family=d.state.families.get(person.family);double oldMaximum=person.maximum(),oldNourishment=person.nourishment;CityEconomy.require(r.revision()==d.state.revision,"数据已更新，请重新打开");switch(r.op()){
  case "ruralenable"->d.enable(p.server,CityData.get(p.server).require(family.city));
  case "ruralage"->{person.age=RuralRules.Age.values()[(person.age.ordinal()+1)%RuralRules.Age.values().length];person.stageTicks=0;person.nourishment=Math.min(person.nourishment,person.maximum());}
  case "ruralpregnant"->{if(!person.pregnant)CityEconomy.require(person.age!=RuralRules.Age.INFANT&&person.age!=RuralRules.Age.CHILD&&person.age!=RuralRules.Age.ELDER&&RuralRules.reserved(family,d.state.people)<10,"年龄不符或家庭没有预留名额");person.pregnant=!person.pregnant;}
  case "ruraljoin"->{var target=d.state.people.get(pendingPartner.get(p.getUUID()));CityEconomy.require(target!=null&&!target.family.equals(person.family),"先选目标家庭成员，再选待加入者");var destination=d.state.families.get(target.family);CityEconomy.require(family.city.equals(destination.city)&&family.members.size()==1,"仅同城独立居民可加入家庭");RuralRules.admit(destination,person,d.state.people);for(var box:d.state.boxes.values())if(family.id.equals(box.stock.family))box.stock.family=destination.id;d.state.families.remove(family.id);} case "ruralcare"->{CityEconomy.require(person.age==RuralRules.Age.INFANT,"先选照护者，再选婴儿，点击指定照护");var adult=d.state.people.get(pendingPartner.get(p.getUUID()));CityEconomy.require(adult!=null&&adult.age.ordinal()>=2&&adult.family.equals(person.family),"照护者须为同家庭成人");person.caregiver=adult.id;RuralRules.refreshCaregivers(d.state.people);} case "ruralwheatprice"->{CityEconomy.require(person.role==RuralRules.Role.MERCHANT,"仅头人可定价");person.wheatPrice=person.wheatPrice%10+1;} case "ruralbreadprice"->{CityEconomy.require(person.role==RuralRules.Role.MERCHANT,"仅头人可定价");person.breadPrice=person.breadPrice%10+1;} case "ruralrelation"->relation(d,p,person,r.value());
  default->throw new IllegalArgumentException("未知农村操作");}if(r.op().equals("ruralage")||r.op().equals("ruralpregnant"))person.nourishment=person.maximum()*(oldMaximum<=0?1:oldNourishment/oldMaximum);RuralRules.refreshCaregivers(d.state.people);d.state.revision++;d.setDirty();snapshot(p,id,"已保存");}catch(Exception ex){say(p,ex.getMessage());}}
 static void relation(RuralSettlement d,ServerPlayer player,RuralRules.Person a,String mode){if(mode.equals("single")){if(a.spouse!=null){var old=d.state.people.get(a.spouse);if(old!=null){old.spouse=null;old.marriage=RuralRules.Marriage.NONE;}}if(a.lover!=null){var old=d.state.people.get(a.lover);if(old!=null)old.lover=null;}a.spouse=null;a.lover=null;a.marriage=RuralRules.Marriage.NONE;return;}UUID other=pendingPartner.get(player.getUUID());var b=d.state.people.get(other);CityEconomy.require(b!=null&&!a.id.equals(b.id),"先依次选择两位NPC");CityEconomy.require(a.age.ordinal()>=2&&b.age.ordinal()>=2,"仅成人可建立关系");if(mode.equals("love")){CityEconomy.require((a.lover==null||a.lover.equals(b.id))&&(b.lover==null||b.lover.equals(a.id)),"先解除原恋爱关系");a.lover=b.id;b.lover=a.id;return;}CityEconomy.require(mode.equals("factual")||mode.equals("legal"),"婚姻类型错误");CityEconomy.require((a.spouse==null||a.spouse.equals(b.id))&&(b.spouse==null||b.spouse.equals(a.id)),"先解除原婚姻");var fa=d.state.families.get(a.family);var fb=d.state.families.get(b.family);CityEconomy.require(fa.city.equals(fb.city),"不能跨城合户");if(fa!=fb){CityEconomy.require(RuralRules.reserved(fa,d.state.people)+RuralRules.reserved(fb,d.state.people)<=10,"合并后家庭超过10人");for(UUID id:new ArrayList<>(fb.members))RuralRules.admit(fa,d.state.people.get(id),d.state.people);for(var box:d.state.boxes.values())if(fb.id.equals(box.stock.family))box.stock.family=fa.id;d.state.families.remove(fb.id);}a.spouse=b.id;b.spouse=a.id;a.marriage=b.marriage=mode.equals("legal")?RuralRules.Marriage.LEGAL:RuralRules.Marriage.FACTUAL;}
}






